  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --panel: #111827;
      --panel-2: #0f172a;
      --text: #e5e7eb;
      --muted: #94a3b8;
      --border: #243047;
      --accent: #60a5fa;
      --accent-2: #3b82f6;
      --error: #f87171;
      --shadow: 0 24px 80px rgba(0, 0, 0, 0.45);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      display: grid;
      place-items: center;
      background:
        radial-gradient(circle at top, rgba(96, 165, 250, 0.14), transparent 40%),
        linear-gradient(180deg, #08101f 0%, #0b1020 100%);
      color: var(--text);
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      padding: 24px;
    }

    .support-card {
      width: min(100%, 640px);
      background: linear-gradient(180deg, rgba(17, 24, 39, 0.96), rgba(15, 23, 42, 0.96));
      border: 1px solid rgba(148, 163, 184, 0.16);
      border-radius: 24px;
      box-shadow: var(--shadow);
      padding: 32px;
      backdrop-filter: blur(16px);
    }

    h1 {
      margin: 0 0 8px;
      font-size: clamp(1.75rem, 2.5vw, 2.25rem);
      line-height: 1.1;
    }

    p {
      margin: 0 0 24px;
      color: var(--muted);
      line-height: 1.6;
    }

    form {
      display: grid;
      gap: 18px;
    }

    .form-field {
      display: grid;
      gap: 8px;
    }

    label {
      font-weight: 600;
      font-size: 0.95rem;
    }

    input {
      width: 100%;
      border: 1px solid var(--border);
      background: rgba(3, 7, 18, 0.72);
      color: var(--text);
      border-radius: 14px;
      padding: 14px 16px;
      font: inherit;
      outline: none;
      transition: border-color 0.18s ease, box-shadow 0.18s ease, transform 0.18s ease;
    }

    input::placeholder {
      color: #64748b;
    }

    input:focus {
      border-color: rgba(96, 165, 250, 0.9);
      box-shadow: 0 0 0 4px rgba(59, 130, 246, 0.16);
    }

    .helper-text {
      color: var(--muted);
      font-size: 0.88rem;
      line-height: 1.45;
    }

    .field-message {
      color: var(--error);
      font-size: 0.88rem;
      line-height: 1.45;
      min-height: 1.25em;
    }

    .field-message[hidden] {
      display: none;
    }

    .form-field.invalid input {
      border-color: rgba(248, 113, 113, 0.9);
      box-shadow: 0 0 0 4px rgba(248, 113, 113, 0.12);
    }

    button {
      margin-top: 4px;
      border: 0;
      border-radius: 14px;
      padding: 14px 18px;
      font: inherit;
      font-weight: 700;
      color: white;
      background: linear-gradient(180deg, var(--accent), var(--accent-2));
      cursor: pointer;
      box-shadow: 0 14px 30px rgba(59, 130, 246, 0.24);
      transition: transform 0.18s ease, box-shadow 0.18s ease;
    }

    button:hover {
      transform: translateY(-1px);
      box-shadow: 0 18px 36px rgba(59, 130, 246, 0.3);
    }

    button:active {
      transform: translateY(0);
    }
  </style>
</head>
<body>
  <main class="support-card">
    <h1>Contact Support</h1>
    <p>Send us a message and we’ll get back to you as soon as possible.</p>

    <form id="support-form" novalidate>
      <div class="form-field">
        <label for="full-name">Full name</label>
        <input id="full-name" name="fullName" type="text" autocomplete="name" required placeholder="Jane Doe" />
        <div class="field-message" id="full-name-error" hidden></div>
      </div>

      <div class="form-field">
        <label for="email-address">Email address</label>
        <input id="email-address" name="emailAddress" type="email" autocomplete="email" required placeholder="jane@example.com" />
        <div class="field-message" id="email-address-error" hidden></div>
      </div>

      <div class="form-field">
        <label for="phone-number">Phone number</label>
        <input id="phone-number" name="phoneNumber" type="tel" autocomplete="tel" placeholder="+1 (555) 123-4567" />
        <div class="helper-text">Optional. Use a format like +1 (555) 123-4567 or 555-123-4567.</div>
        <div class="field-message" id="phone-number-error" hidden></div>
      </div>

      <button type="submit">Submit Request</button>
    </form>
  </main>

  <script>
    const form = document.getElementById('support-form');
    const fields = {
      fullName: {
        input: document.getElementById('full-name'),
        error: document.getElementById('full-name-error'),
        validate() {
          if (!this.input.value.trim()) {
            return 'Full name is required.';
          }
          return '';
        }
      },
      emailAddress: {
        input: document.getElementById('email-address'),
        error: document.getElementById('email-address-error'),
        validate() {
          if (!this.input.value.trim()) {
            return 'Email address is required.';
          }
          if (!this.input.validity.valid) {
            return 'Enter a valid email address.';
          }
          return '';
        }
      },
      phoneNumber: {
        input: document.getElementById('phone-number'),
        error: document.getElementById('phone-number-error'),
        validate() {
          const value = this.input.value.trim();
          if (!value) {
            return '';
          }
          const phonePattern = /^[+()\-.\s\d]{7,}$/;
          return phonePattern.test(value) ? '' : 'Enter a valid phone number format.';
        }
      }
    };

    function setFieldState(field, message) {
      const wrapper = field.input.closest('.form-field');
      wrapper.classList.toggle('invalid', Boolean(message));
      field.input.setAttribute('aria-invalid', Boolean(message));
      field.error.textContent = message;
      field.error.hidden = !message;
    }

    function validateForm() {
      let isValid = true;
      for (const field of Object.values(fields)) {
        const message = field.validate();
        setFieldState(field, message);
        if (message) isValid = false;
      }
      return isValid;
    }

    form.addEventListener('submit', (event) => {
      event.preventDefault();
      if (validateForm()) {
        form.reset();
        for (const field of Object.values(fields)) {
          setFieldState(field, '');
        }
      }
    });

    for (const field of Object.values(fields)) {
      field.input.addEventListener('input', () => {
        if (field.error.hidden) return;
        setFieldState(field, field.validate());
      });
    }
  </script>
</body>
</html>
