         <input id="phone-number" name="phoneNumber" type="tel" autocomplete="tel" placeholder="+1 (555) 123-4567" />
         <div class="helper-text">Optional. Use a format like +1 (555) 123-4567 or 555-123-4567.</div>
         <div class="field-message" id="phone-number-error" hidden></div>
       </div>

       <button type="submit">Submit Request</button>
     </form>
   </main>

   <script>
     const form = document.getElementById('support-form');
     const fields = {
       fullName: {
         input: document.getElementById('full-name'),
         error: document.getElementById('full-name-error'),
         validate() {
           if (!this.input.value.trim()) {
             return 'Full name is required.';
           }
           return '';
         }
       },
       emailAddress: {
         input: document.getElementById('email-address'),
         error: document.getElementById('email-address-error'),
         validate() {
           if (!this.input.value.trim()) {
             return 'Email address is required.';
           }
           if (!this.input.validity.valid) {
             return 'Enter a valid email address.';
           }
           return '';
         }
       },
       phoneNumber: {
         input: document.getElementById('phone-number'),
         error: document.getElementById('phone-number-error'),
         validate() {
           const value = this.input.value.trim();
           if (!value) {
             return '';
           }
           const phonePattern = /^[+()\-.\s\d]{7,}$/;
           return phonePattern.test(value) ? '' : 'Enter a valid phone number format.';
         }
       }
     };

     function setFieldState(field, message) {
       const wrapper = field.input.closest('.form-field');
       wrapper.classList.toggle('invalid', Boolean(message));
       field.input.setAttribute('aria-invalid', Boolean(message));
       field.error.textContent = message;
       field.error.hidden = !message;
     }

     function validateForm() {
       let isValid = true;
       for (const field of Object.values(fields)) {
         const message = field.validate();
         setFieldState(field, message);
         if (message) isValid = false;
       }
       return isValid;
     }

     form.addEventListener('submit', (event) => {
       event.preventDefault();
       if (validateForm()) {
         form.reset();
         for (const field of Object.values(fields)) {
           setFieldState(field, '');
         }
       }
     });

     for (const field of Object.values(fields)) {
       field.input.addEventListener('input', () => {
         if (field.error.hidden) return;
         setFieldState(field, field.validate());
       });
     }
   </script>
 </body>
 </html>

